import React, { useState, useEffect } from 'react';
import { 
  BrainCircuit, LogOut, User, GraduationCap, ArrowRight,
  ShieldCheck, Wallet, Award, Save, Calendar, Search, 
  LayoutDashboard, AlertCircle, Users, FileText,
  TrendingDown, Filter, Download, Plus, Trash2, 
  ChevronRight, Settings, Info, Lock, Mail, X,
  Activity, Home, MapPin, BookOpen, CheckCircle2,
  Edit3, Megaphone, BellRing, ClipboardCheck
} from 'lucide-react';

// --- MOCK DATA ---
const INITIAL_STUDENTS = [
  { id: '1', name: 'Juan Dela Cruz', income: 8500, absences: 14, risk: 78, status: 'At Risk', email: 'juan@univ.edu', studyTime: 8, distance: 15, parentEdu: 1, interventions: [] },
  { id: '2', name: 'Maria Santos', income: 28000, absences: 2, risk: 12, status: 'Stable', email: 'maria@univ.edu', studyTime: 25, distance: 2, parentEdu: 4, interventions: [] },
  { id: '3', name: 'Kevin Lee', income: 14500, absences: 6, risk: 32, status: 'Stable', email: 'kevin@univ.edu', studyTime: 12, distance: 8, parentEdu: 2, interventions: [] },
];

const MOCK_USERS = [
  { id: 'u1', name: 'Dr. Smith', role: 'teacher', email: 'smith@univ.edu' },
  { id: 'u2', name: 'Admin Jane', role: 'admin', email: 'admin@univ.edu' },
];

// --- HELPER COMPONENTS ---

const RiskIndicator = ({ label, value, max, icon: Icon, colorClass }) => (
  <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100">
    <div className="flex justify-between items-center mb-2">
      <div className="flex items-center gap-2">
        <Icon size={16} className="text-slate-400" />
        <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">{label}</span>
      </div>
      <span className="text-xs font-black text-slate-800">{value}</span>
    </div>
    <div className="w-full h-1.5 bg-slate-200 rounded-full overflow-hidden">
      <div 
        className={`h-full transition-all duration-1000 ${colorClass}`} 
        style={{ width: `${Math.min(100, (parseFloat(String(value).replace(/[^0-9.]/g, '')) / max) * 100)}%` }}
      />
    </div>
  </div>
);

// --- DASHBOARD COMPONENTS ---

const StudentPortal = ({ studentData, updateStudent, notifications }) => {
  const [activeTab, setActiveTab] = useState('home');
  const [profile, setProfile] = useState(studentData || INITIAL_STUDENTS[0]);

  // Sync internal state if props change (e.g. teacher updates data)
  useEffect(() => {
    if (studentData) setProfile(studentData);
  }, [studentData]);

  const currentRisk = profile.risk;
  const successRate = 100 - currentRisk;

  const getRiskStatus = (score) => {
    if (score > 50) return { color: 'text-rose-500', bg: 'bg-rose-50', label: 'High Risk' };
    if (score > 20) return { color: 'text-amber-500', bg: 'bg-amber-50', label: 'Moderate' };
    return { color: 'text-emerald-500', bg: 'bg-emerald-50', label: 'Low Risk' };
  };

  // --- INTERACTION LOGIC ---
  const markInterventionDone = (idx) => {
    const updatedInterventions = [...profile.interventions];
    updatedInterventions.splice(idx, 1);
    
    // Reward: Lower risk score by 5 points for completing a task
    const newRisk = Math.max(0, profile.risk - 5);
    
    const updatedProfile = { 
      ...profile, 
      risk: newRisk,
      interventions: updatedInterventions 
    };

    setProfile(updatedProfile);
    updateStudent(updatedProfile); // Update Global State
    alert("Task Completed! Risk Score Lowered.");
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
      {/* Sidebar */}
      <div className="lg:col-span-3 space-y-2">
        <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-100 mb-6">
          <div className="w-16 h-16 bg-indigo-100 rounded-2xl flex items-center justify-center mb-4">
            <User className="text-indigo-600" size={32} />
          </div>
          <h3 className="font-black text-slate-800 leading-tight">{profile.name}</h3>
          <p className="text-xs font-bold text-slate-400">Student ID: 2024-00{profile.id}</p>
        </div>
        
        {/* NOTIFICATION BANNER (Admin Functionality) */}
        {notifications.length > 0 && (
          <div className="bg-indigo-600 p-6 rounded-[2rem] text-white shadow-xl shadow-indigo-200 mb-6 animate-pulse">
             <div className="flex items-center gap-2 mb-2">
               <Megaphone size={16}/>
               <h4 className="text-xs font-black uppercase tracking-widest">Broadcast</h4>
             </div>
             <p className="text-xs font-bold leading-relaxed opacity-90">{notifications[notifications.length-1].message}</p>
          </div>
        )}

        <button onClick={() => setActiveTab('home')} className={`w-full flex items-center gap-3 px-6 py-4 rounded-2xl font-bold transition-all ${activeTab === 'home' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:bg-white'}`}>
          <LayoutDashboard size={20} /> My Progress
        </button>
        <button onClick={() => setActiveTab('profile')} className={`w-full flex items-center gap-3 px-6 py-4 rounded-2xl font-bold transition-all ${activeTab === 'profile' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:bg-white'}`}>
          <Settings size={20} /> Edit Profile
        </button>
      </div>

      <div className="lg:col-span-9 space-y-6">
        {activeTab === 'home' ? (
          <>
            <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm flex flex-col md:flex-row gap-8 items-center">
              <div className="relative w-40 h-40 flex items-center justify-center">
                 <svg className="w-full h-full transform -rotate-90">
                   <circle cx="80" cy="80" r="70" stroke="currentColor" strokeWidth="12" fill="transparent" className="text-slate-100" />
                   <circle 
                    cx="80" 
                    cy="80" 
                    r="70" 
                    stroke="currentColor" 
                    strokeWidth="12" 
                    fill="transparent" 
                    strokeDasharray={440} 
                    strokeDashoffset={440 - (440 * successRate) / 100} 
                    className="text-indigo-600 transition-all duration-1000" 
                   />
                 </svg>
                 <div className="absolute inset-0 flex flex-col items-center justify-center">
                    <span className="text-3xl font-black text-slate-800">{successRate}%</span>
                    <span className="text-[10px] font-bold text-slate-400 uppercase">Success Rate</span>
                 </div>
              </div>
              <div className="flex-1 space-y-4">
                <h2 className="text-2xl font-black text-slate-800 text-center md:text-left">Welcome Back, {profile.name.split(' ')[0]}</h2>
                <p className="text-slate-500 text-sm leading-relaxed text-center md:text-left">
                  Your risk status is <span className={`font-bold ${getRiskStatus(currentRisk).color}`}>{getRiskStatus(currentRisk).label}</span>. 
                  {profile.interventions.length > 0 && " You have pending tasks."}
                </p>
                <div className="flex flex-wrap gap-2 justify-center md:justify-start">
                  <div className="px-4 py-2 bg-indigo-50 text-indigo-600 rounded-xl text-xs font-bold flex items-center gap-2"><Wallet size={14}/> PHP {(profile.income || 0).toLocaleString()}/mo</div>
                  <div className="px-4 py-2 bg-rose-50 text-rose-600 rounded-xl text-xs font-bold flex items-center gap-2"><AlertCircle size={14}/> {profile.absences} Absences</div>
                </div>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* INTERACTIVE ACTION CENTER */}
              <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm space-y-4">
                <h4 className="font-black text-slate-800 flex items-center gap-2 text-lg">
                  <ClipboardCheck className="text-indigo-500"/> Action Items
                  {profile.interventions.length > 0 && <span className="bg-rose-500 text-white text-[10px] px-2 py-0.5 rounded-full">{profile.interventions.length}</span>}
                </h4>
                <div className="space-y-3">
                  {profile.interventions.length > 0 ? (
                    profile.interventions.map((task, idx) => (
                      <div key={idx} className="p-4 bg-indigo-50 rounded-2xl border border-indigo-100 flex items-center justify-between group">
                        <div className="flex items-center gap-3">
                          <div className="w-8 h-8 bg-white rounded-full flex items-center justify-center text-indigo-600 shadow-sm">
                            <BellRing size={14}/>
                          </div>
                          <div>
                             <p className="text-xs font-black text-indigo-900 uppercase tracking-wide">Assigned Task</p>
                             <p className="text-sm text-indigo-800 font-bold">{task}</p>
                          </div>
                        </div>
                        <button 
                          onClick={() => markInterventionDone(idx)}
                          className="bg-white text-emerald-500 p-2 rounded-xl shadow-sm hover:bg-emerald-500 hover:text-white transition-all" 
                          title="Mark as Done"
                        >
                          <CheckCircle2 size={18}/>
                        </button>
                      </div>
                    ))
                  ) : (
                    <div className="p-8 text-center border-2 border-dashed border-slate-200 rounded-2xl">
                      <p className="text-slate-400 text-xs font-bold">No pending actions. Keep it up!</p>
                    </div>
                  )}
                </div>
              </div>

              {/* AI INSIGHTS */}
              <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm space-y-4">
                <h4 className="font-black text-slate-800 flex items-center gap-2 text-lg"><ShieldCheck className="text-emerald-500"/> AI Analysis</h4>
                <div className="space-y-3">
                  {profile.absences > 10 && (
                    <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100 text-sm text-slate-600">
                      <span className="font-bold text-rose-500">Alert:</span> High absenteeism ({profile.absences}) detected.
                    </div>
                  )}
                  {profile.income < 15000 && (
                    <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100 text-sm text-slate-600">
                      <span className="font-bold text-amber-500">Notice:</span> Eligible for TES financial grant.
                    </div>
                  )}
                  {profile.absences <= 5 && (
                    <div className="p-4 bg-emerald-50 rounded-2xl border border-emerald-100 text-sm text-emerald-600 font-bold">
                      Academic standing is excellent.
                    </div>
                  )}
                </div>
              </div>
            </div>
          </>
        ) : (
          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm animate-in slide-in-from-bottom-4 duration-500">
              <h2 className="text-xl font-black text-slate-800 mb-6">Profile Settings</h2>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase ml-2 tracking-widest">Full Name</label>
                  <input className="w-full p-4 bg-slate-50 border-transparent focus:border-indigo-500 border rounded-2xl outline-none transition-all font-bold" value={profile.name} onChange={e => setProfile({...profile, name: e.target.value})} />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase ml-2 tracking-widest">Monthly Income (PHP)</label>
                  <input type="number" className="w-full p-4 bg-slate-50 border-transparent focus:border-indigo-500 border rounded-2xl outline-none transition-all font-bold" value={profile.income} onChange={e => setProfile({...profile, income: parseInt(e.target.value) || 0})} />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase ml-2 tracking-widest">Total Absences</label>
                  <input type="number" className="w-full p-4 bg-slate-50 border-transparent focus:border-indigo-500 border rounded-2xl outline-none transition-all font-bold" value={profile.absences} onChange={e => setProfile({...profile, absences: parseInt(e.target.value) || 0})} />
                </div>
              </div>
              <button 
                onClick={() => {
                  updateStudent(profile); // Updates global state
                  setActiveTab('home');
                  alert("Profile updated and Risk recalculated!");
                }}
                className="mt-8 bg-slate-900 text-white w-full py-5 rounded-2xl font-black uppercase tracking-widest text-xs flex items-center justify-center gap-3 hover:bg-indigo-600 transition-all shadow-xl shadow-slate-200"
              >
                <Save size={18}/> Update & View Progress
              </button>
          </div>
        )}
      </div>
    </div>
  );
};

const TeacherPortal = ({ students, setStudents }) => {
  const [isUploading, setIsUploading] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [selectedStudent, setSelectedStudent] = useState(null);
  const [notification, setNotification] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');
  
  // New State for Editing inside the modal
  const [editMode, setEditMode] = useState(false);
  const [editData, setEditData] = useState({});

  const filteredStudents = students.filter(student => 
    student.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
    student.email.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const handleFileUpload = (event) => {
    const file = event.target.files[0];
    if (!file) return;

    setIsAnalyzing(true);
    const reader = new FileReader();

    reader.onload = (e) => {
      const text = e.target.result;
      const rows = text.split('\n').filter(r => r.trim()).slice(1); 
      
      const newStudents = rows.map((row, index) => {
        const cols = row.split(',').map(col => col.replace(/"/g, '').trim());
        if (cols.length < 4) return null;
        const email = cols[1] || "No Email";
        if (students.some(s => s.email.toLowerCase() === email.toLowerCase())) return null; 

        const income = parseInt(cols[2]) || 0;
        const absences = parseInt(cols[3]) || 0;
        const risk = parseInt(cols[4]) || Math.min(100, (absences * 5) + (income < 10000 ? 20 : 0));

        return {
          id: `csv-${index}-${Date.now()}`,
          name: cols[0] || "Unknown Student",
          email: email,
          income: income,
          absences: absences,
          risk: risk,
          status: risk > 50 ? 'At Risk' : 'Stable',
          studyTime: 10, distance: 5, parentEdu: 2, interventions: []
        };
      }).filter(s => s !== null);

      if (newStudents.length > 0) {
        setStudents(prev => [...prev, ...newStudents]);
        setNotification(`${newStudents.length} new records synced`);
      } else {
        setNotification('No new unique records found');
      }
      setTimeout(() => { setIsAnalyzing(false); setIsUploading(false); setNotification(null); }, 2000);
    };
    reader.readAsText(file);
  };

  const saveEdit = () => {
     const newRisk = Math.min(100, (editData.absences * 5) + (editData.income < 10000 ? 20 : 0));
     const updatedStudent = { ...editData, risk: newRisk, status: newRisk > 50 ? 'At Risk' : 'Stable' };
     setStudents(students.map(s => s.id === updatedStudent.id ? updatedStudent : s));
     setSelectedStudent(updatedStudent);
     setEditMode(false);
     setNotification(`Updated ${updatedStudent.name}.`);
  };

  const deployIntervention = (type) => {
    if (!selectedStudent) return;
    const task = type === 'financial' ? "Apply for TES Subsidy at Admin Office" : "Report to Guidance Office (Rm 102)";
    const updated = { ...selectedStudent, interventions: [...selectedStudent.interventions, task] };
    
    // Update Global State
    setStudents(students.map(s => s.id === updated.id ? updated : s));
    setSelectedStudent(updated); // Update local modal
    setNotification("Intervention Deployed to Student Dashboard");
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tight">Faculty Dashboard</h2>
          <p className="text-slate-400 text-sm font-bold">Identifying academic risks through AI socio-analysis.</p>
        </div>
        <button onClick={() => setIsUploading(true)} className="bg-indigo-600 text-white px-6 py-2 rounded-xl font-bold text-xs flex items-center gap-2 hover:bg-indigo-700 shadow-lg shadow-indigo-100 transition-all">
          <Plus size={16}/> Upload CSV
        </button>
      </div>

      {notification && (
        <div className="bg-emerald-500 text-white p-4 rounded-2xl flex items-center justify-between shadow-lg animate-in slide-in-from-top-4">
          <div className="flex items-center gap-3"><CheckCircle2 size={18}/><span className="font-bold text-sm">{notification}</span></div>
          <button onClick={() => setNotification(null)}><X size={16}/></button>
        </div>
      )}

      {/* Stats and Table code preserved from previous version... */}
      <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden">
        <div className="px-8 py-6 border-b border-slate-100 flex justify-between items-center bg-slate-50/30">
          <h4 className="font-black text-slate-800">Student Registry</h4>
          <input placeholder="Filter students..." className="pl-4 pr-4 py-2 bg-white border border-slate-200 rounded-xl text-xs outline-none focus:border-indigo-500" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} />
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="text-[10px] font-black text-slate-400 uppercase tracking-widest bg-slate-50">
                <th className="px-8 py-4">Student</th>
                <th className="px-8 py-4 text-center">Income</th>
                <th className="px-8 py-4 text-center">Risk</th>
                <th className="px-8 py-4">Active Tasks</th>
                <th className="px-8 py-4"></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredStudents.map((student) => (
                  <tr key={student.id} className="hover:bg-slate-50/50 transition-all group">
                    <td className="px-8 py-5">
                      <div className="flex items-center gap-3">
                        <div className="w-10 h-10 bg-indigo-50 text-indigo-600 rounded-xl flex items-center justify-center font-black shrink-0">{student.name[0]}</div>
                        <div><p className="text-sm font-black text-slate-800">{student.name}</p><p className="text-[10px] text-slate-400 font-bold">{student.email}</p></div>
                      </div>
                    </td>
                    <td className="px-8 py-5 text-center font-bold text-slate-600 text-sm">PHP {student.income.toLocaleString()}</td>
                    <td className="px-8 py-5 text-center"><span className={`px-3 py-1 rounded-full text-[10px] font-black ${student.risk > 50 ? 'bg-rose-100 text-rose-600' : 'bg-emerald-100 text-emerald-600'}`}>{student.risk}%</span></td>
                    <td className="px-8 py-5"><span className="text-[10px] font-bold text-slate-400 uppercase">{student.interventions.length} Pending</span></td>
                    <td className="px-8 py-5 text-right">
                      <button onClick={() => { setSelectedStudent(student); setEditData(student); setEditMode(false); }} className="p-2 bg-slate-100 text-slate-400 rounded-xl hover:bg-indigo-600 hover:text-white transition-all"><Edit3 size={16}/></button>
                    </td>
                  </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* --- DETAILED ANALYSIS & EDIT MODAL --- */}
      {selectedStudent && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-md z-[200] flex items-center justify-center p-4">
           <div className="bg-white w-full max-w-4xl max-h-[90vh] overflow-y-auto rounded-[3rem] shadow-2xl animate-in zoom-in-95 duration-300">
              <div className="sticky top-0 bg-white/80 backdrop-blur-md px-8 py-6 border-b border-slate-100 flex justify-between items-center z-10">
                 <div className="flex items-center gap-4">
                    <div className="w-12 h-12 bg-indigo-600 text-white rounded-2xl flex items-center justify-center font-black text-xl">{selectedStudent.name[0]}</div>
                    <div><h3 className="text-xl font-black text-slate-800">{selectedStudent.name}</h3><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Socioeconomic Profile</p></div>
                 </div>
                 <button onClick={() => setSelectedStudent(null)} className="p-3 hover:bg-slate-100 rounded-2xl transition-all"><X/></button>
              </div>

              <div className="p-8 space-y-8">
                 {editMode ? (
                     <div className="space-y-6">
                        <div className="flex justify-between items-center">
                            <h4 className="text-lg font-black text-slate-800">Edit Student Data</h4>
                            <button onClick={() => setEditMode(false)} className="text-xs font-bold text-rose-500 uppercase">Cancel Editing</button>
                        </div>
                        <div className="grid grid-cols-2 gap-6">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Monthly Income</label>
                                <input type="number" className="w-full p-4 bg-slate-50 rounded-2xl font-bold" value={editData.income} onChange={(e) => setEditData({...editData, income: parseInt(e.target.value) || 0})} />
                            </div>
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Total Absences</label>
                                <input type="number" className="w-full p-4 bg-slate-50 rounded-2xl font-bold" value={editData.absences} onChange={(e) => setEditData({...editData, absences: parseInt(e.target.value) || 0})} />
                            </div>
                        </div>
                        <button onClick={saveEdit} className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase text-xs hover:bg-indigo-700 transition-all">Save & Recalculate Risk</button>
                     </div>
                 ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                        <div className="space-y-6">
                            <div className="flex justify-between items-center">
                                <h4 className="text-xs font-black text-slate-400 uppercase tracking-[0.2em] border-l-4 border-indigo-600 pl-4">Risk Distribution</h4>
                                <button onClick={() => setEditMode(true)} className="flex items-center gap-2 text-[10px] font-black uppercase text-indigo-600 bg-indigo-50 px-3 py-1 rounded-lg hover:bg-indigo-100 transition-all">
                                    <Edit3 size={14}/> Edit Data
                                </button>
                            </div>
                            <div className="grid grid-cols-1 gap-4">
                                <RiskIndicator label="Monthly Income" value={`PHP ${selectedStudent.income.toLocaleString()}`} max={50000} icon={Wallet} colorClass={selectedStudent.income < 10000 ? "bg-rose-500" : "bg-emerald-500"} />
                                <RiskIndicator label="Absences" value={`${selectedStudent.absences} Days`} max={30} icon={Calendar} colorClass={selectedStudent.absences > 10 ? "bg-rose-500" : "bg-amber-500"} />
                            </div>
                        </div>

                        <div className="space-y-6">
                            <h4 className="text-xs font-black text-slate-400 uppercase tracking-[0.2em] border-l-4 border-emerald-500 pl-4">Deploy Interventions</h4>
                            <div className="bg-slate-50 rounded-[2rem] border border-slate-100 p-6 space-y-4">
                                <div onClick={() => deployIntervention('financial')} className="p-4 bg-white rounded-xl border border-slate-100 flex justify-between items-center hover:border-indigo-300 transition-all cursor-pointer group">
                                    <div className="flex items-center gap-3"><Award className="text-emerald-600 group-hover:scale-110 transition-transform"/><p className="text-xs font-black text-slate-800 uppercase">Grant Subsidy</p></div>
                                    <Plus size={16} className="text-slate-300"/>
                                </div>
                                <div onClick={() => deployIntervention('counseling')} className="p-4 bg-white rounded-xl border border-slate-100 flex justify-between items-center hover:border-indigo-300 transition-all cursor-pointer group">
                                    <div className="flex items-center gap-3"><Activity className="text-rose-600 group-hover:scale-110 transition-transform"/><p className="text-xs font-black text-slate-800 uppercase">Guidance Counseling</p></div>
                                    <Plus size={16} className="text-slate-300"/>
                                </div>
                            </div>
                        </div>
                    </div>
                 )}
              </div>
           </div>
        </div>
      )}

      {/* --- UPLOAD MODAL (Preserved) --- */}
      {isUploading && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[100] flex items-center justify-center p-6">
          <div className="bg-white w-full max-w-md rounded-[2.5rem] p-8 space-y-6 shadow-2xl animate-in zoom-in-95 duration-200">
             {/* Upload UI Code same as before */}
             <div className="text-center">
              <div className="w-20 h-20 bg-indigo-50 rounded-[2rem] flex items-center justify-center mx-auto mb-6"><FileText className="text-indigo-600" size={32} /></div>
              <h3 className="text-2xl font-black text-slate-800 tracking-tight">CSV Scrutiny</h3>
            </div>
            <label className="border-2 border-dashed border-slate-200 rounded-[2rem] p-12 text-center group hover:border-indigo-400 transition-all cursor-pointer block">
              <input type="file" className="hidden" accept=".csv" onChange={handleFileUpload} />
              {isAnalyzing ? <p className="text-[10px] font-black text-indigo-600 uppercase">Analyzing...</p> : <><Plus className="mx-auto text-slate-300 mb-4" size={32} /><p className="text-xs font-black text-slate-400 uppercase">Select File</p></>}
            </label>
            <button onClick={() => setIsUploading(false)} className="w-full py-4 bg-slate-50 text-slate-400 rounded-2xl font-black text-xs uppercase hover:bg-slate-100">Cancel</button>
          </div>
        </div>
      )}
    </div>
  );
};

// --- ADMIN PORTAL (Restored Functionality) ---
const AdminPortal = ({ broadcastAlert }) => {
    const [msg, setMsg] = useState("");
    return (
        <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
             <div className="flex justify-between items-center">
                <div>
                  <h2 className="text-3xl font-black text-slate-800 tracking-tight">System Admin</h2>
                  <p className="text-slate-400 text-sm font-bold">Secure Command Center</p>
                </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
                  <h4 className="font-black text-slate-800 mb-6 flex items-center gap-2"><Megaphone className="text-rose-500"/> System Broadcast</h4>
                  <textarea 
                    className="w-full p-4 bg-slate-50 border-slate-100 border rounded-2xl outline-none focus:border-indigo-500 text-sm font-bold min-h-[120px] transition-all" 
                    placeholder="Type a system-wide announcement (e.g., Classes suspended...)"
                    value={msg}
                    onChange={e => setMsg(e.target.value)}
                  />
                  <button 
                    onClick={() => { broadcastAlert(msg); setMsg(""); alert("Alert Sent to All Dashboards"); }} 
                    className="w-full mt-4 py-4 bg-rose-500 text-white rounded-2xl font-black uppercase tracking-widest text-xs hover:bg-rose-600 transition-all shadow-lg shadow-rose-200"
                  >
                    Broadcast Alert
                  </button>
              </div>
              <div className="bg-slate-900 p-8 rounded-[2.5rem] text-white flex flex-col justify-center items-center text-center space-y-4">
                  <Lock size={48} className="text-indigo-400 mb-4"/>
                  <h3 className="text-xl font-black">Secure Environment</h3>
                  <p className="text-xs text-slate-400 leading-relaxed max-w-xs">System operating at 100% capacity. Mock database integrity check passed.</p>
              </div>
            </div>
        </div>
    );
};

// --- MAIN CONTROLLER ---

export default function App() {
  const [view, setView] = useState('landing'); 
  const [role, setRole] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [loginEmail, setLoginEmail] = useState('');

  // GLOBAL STATE (Lifted Up)
  const [students, setStudents] = useState(INITIAL_STUDENTS);
  const [notifications, setNotifications] = useState([]);
  const [currentUserData, setCurrentUserData] = useState(null);

  const handleLoginSubmit = (e) => {
    e.preventDefault();
    setIsLoading(true);
    setTimeout(() => {
      if (role === 'student') {
          const studentFound = students.find(s => s.email.toLowerCase() === loginEmail.toLowerCase());
          if (studentFound) {
              setCurrentUserData(studentFound);
              setView('dashboard');
          } else {
              // Fallback for demo convenience
              if(loginEmail === '') { setCurrentUserData(students[0]); setView('dashboard'); }
              else alert("Email not found in student database.");
          }
      } else {
          setView('dashboard');
      }
      setIsLoading(false);
    }, 1000);
  };

  const updateStudent = (updatedData) => {
     setStudents(students.map(s => s.id === updatedData.id ? updatedData : s));
     if(currentUserData && currentUserData.id === updatedData.id) setCurrentUserData(updatedData);
  };

  const broadcastAlert = (msg) => {
     setNotifications(prev => [...prev, { id: Date.now(), message: msg }]);
  };

  // Views Render
  if (view === 'landing') {
    return (
      <div className="min-h-screen bg-[#020617] flex items-center justify-center p-6 text-white overflow-hidden relative">
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-indigo-600/20 blur-[120px] rounded-full"></div>
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-blue-600/20 blur-[120px] rounded-full"></div>

        <div className="relative z-10 w-full max-w-lg text-center animate-in fade-in zoom-in-95 duration-1000">
          <div className="inline-flex p-4 rounded-[2.5rem] bg-indigo-500/10 border border-indigo-500/20 mb-10 shadow-2xl shadow-indigo-500/10">
            <BrainCircuit className="text-indigo-400 w-12 h-12" />
          </div>
          <h1 className="text-6xl font-black mb-4 tracking-tighter uppercase italic leading-none">Success<span className="text-indigo-500">Predict</span></h1>
          <p className="text-slate-500 text-[11px] font-black uppercase tracking-[0.4em] mb-12">Empowering Student Futures with Socio-AI</p>
          <div className="space-y-4">
            {['student', 'teacher', 'admin'].map((id) => (
              <button 
                key={id} 
                onClick={() => { setRole(id); setView('login'); setLoginEmail(''); }} 
                className={`w-full group bg-slate-900/50 backdrop-blur-md border border-slate-800 p-6 rounded-[2rem] flex items-center justify-between transition-all hover:bg-indigo-600 hover:border-indigo-400 hover:scale-[1.02] active:scale-95`}
              >
                <div className="flex items-center gap-4 text-left">
                   <div className="w-10 h-10 rounded-xl bg-slate-800 flex items-center justify-center group-hover:bg-indigo-500 transition-colors">
                      {id === 'student' && <GraduationCap size={18}/>}
                      {id === 'teacher' && <Users size={18}/>}
                      {id === 'admin' && <ShieldCheck size={18}/>}
                   </div>
                   <span className="font-black text-sm uppercase tracking-widest">{id} Portal</span>
                </div>
                <ArrowRight size={20} className="text-slate-700 group-hover:text-white transition-all transform group-hover:translate-x-1" />
              </button>
            ))}
          </div>
          <p className="mt-12 text-slate-600 text-[10px] font-black uppercase tracking-[0.2em]">© 2024 University Academic Intelligence Systems</p>
        </div>
      </div>
    );
  }

  if (view === 'login') {
    return (
      <div className="min-h-screen bg-[#020617] flex items-center justify-center p-6 text-white overflow-hidden relative">
        <div className="absolute top-0 left-0 w-full h-full bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-indigo-500/5 via-transparent to-transparent"></div>
        <div className="w-full max-w-md space-y-8 relative z-10 animate-in fade-in slide-in-from-bottom-8 duration-500">
           <button onClick={() => setView('landing')} className="group text-slate-500 hover:text-white flex items-center gap-2 text-[10px] font-black uppercase tracking-widest transition-all">
             <ArrowRight size={16} className="rotate-180 transition-transform group-hover:-translate-x-1" /> Back to Portals
           </button>
           <div className="bg-[#0f172a] p-10 rounded-[3.5rem] border border-slate-800 shadow-2xl space-y-8">
              <div className="text-center">
                <h2 className="text-2xl font-black uppercase tracking-tight">{role} Access</h2>
                <p className="text-slate-500 text-[10px] font-black uppercase tracking-widest mt-1">Authenticated Entry Required</p>
              </div>
              <form onSubmit={handleLoginSubmit} className="space-y-4">
                 <div className="space-y-1">
                   <label className="text-[10px] font-black text-slate-600 uppercase ml-2 tracking-widest">Email Address</label>
                   <input required className="w-full p-4 bg-slate-900 border border-slate-800 rounded-2xl outline-none focus:border-indigo-500 font-bold text-white placeholder:text-slate-700 transition-all" placeholder="name@univ.edu" value={loginEmail} onChange={(e) => setLoginEmail(e.target.value)} />
                 </div>
                 <div className="space-y-1">
                   <label className="text-[10px] font-black text-slate-600 uppercase ml-2 tracking-widest">Password</label>
                   <input required type="password" defaultValue="demo123" className="w-full p-4 bg-slate-900 border border-slate-800 rounded-2xl outline-none focus:border-indigo-500 font-bold text-white placeholder:text-slate-700 transition-all" />
                 </div>
                 <button type="submit" disabled={isLoading} className="w-full py-5 bg-indigo-600 text-white rounded-2xl font-black uppercase tracking-widest text-xs shadow-xl shadow-indigo-600/20 hover:bg-indigo-500 active:scale-95 transition-all disabled:opacity-50">
                    {isLoading ? 'Authenticating...' : 'Enter Dashboard'}
                 </button>
              </form>
              <p className="text-center text-[10px] text-slate-600 font-bold">Use "demo123" for any account</p>
           </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900">
      <nav className="bg-white/80 backdrop-blur-xl border-b sticky top-0 z-[80] px-8 py-4 flex justify-between items-center shadow-sm">
        <div className="flex items-center gap-3 font-black text-2xl tracking-tighter italic select-none">
          <BrainCircuit className="text-indigo-600" size={22}/> SUCCESS<span className="text-indigo-600">PREDICT</span>
          <span className="hidden md:block h-6 w-[1px] bg-slate-200 mx-2"></span>
          <span className="hidden md:block text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 not-italic">v2.4 LTS</span>
        </div>
        <div className="flex items-center gap-4">
          <div className="hidden sm:flex flex-col items-end mr-2">
            <span className="text-xs font-black text-slate-800 uppercase tracking-tighter">Authorized {role}</span>
            <span className="text-[10px] font-bold text-emerald-500">System Online</span>
          </div>
          <button onClick={() => { setView('landing'); setRole(null); setCurrentUserData(null); }} className="bg-rose-50 text-rose-500 p-3 rounded-2xl hover:bg-rose-100 hover:text-rose-600 active:scale-90 transition-all shadow-sm">
            <LogOut size={20} />
          </button>
        </div>
      </nav>
      
      <main className="max-w-7xl mx-auto p-6 lg:p-12">
        {role === 'student' && <StudentPortal studentData={currentUserData} updateStudent={updateStudent} notifications={notifications}/>}
        {role === 'teacher' && <TeacherPortal students={students} setStudents={setStudents} />}
        {role === 'admin' && <AdminPortal broadcastAlert={broadcastAlert} />}
      </main>
      
      <footer className="max-w-7xl mx-auto p-12 text-center border-t border-slate-100">
         <p className="text-[10px] font-black text-slate-300 uppercase tracking-[0.4em]">SuccessPredict AI Core — Secure Academic Environment</p>
      </footer>
    </div>
  );
}
